class QueryBenchmarkDirectoryCleanupTest {
	@Test
	void successfulShutdownDeletesOwnedDirectoryAfterClosing(@TempDir Path root) throws Exception {
		Path owned = Files.createDirectory(root.resolve("native"));
		Files.writeString(owned.resolve("values.dat"), "owned native data");
		SailRepository repository = mock(SailRepository.class);
		doAnswer(invocation -> {
			assertTrue(Files.exists(owned), "files remain until repository shutdown finishes");
			return null;
		}).when(repository).shutDown();
		QueryBenchmarkTest.cleanupRepository(repository, owned.toFile());
		verify(repository).shutDown();
		assertFalse(Files.exists(owned), "explicit owner removes safely closed native files");
	}

	@Test
	void failedShutdownRetainsNativeFilesAndOriginalFailure(@TempDir Path root) throws Exception {
		Path owned = Files.createDirectory(root.resolve("native"));
		Path data = Files.writeString(owned.resolve("values.dat"), "owned native data");
		SailRepository repository = mock(SailRepository.class);
		IllegalStateException failure = new IllegalStateException("shutdown failed");
		doThrow(failure).when(repository).shutDown();
		assertSame(failure, assertThrows(IllegalStateException.class,
				() -> QueryBenchmarkTest.cleanupRepository(repository, owned.toFile())));
		assertTrue(Files.exists(data), "unsafe native files survive unsuccessful shutdown");
	}

	@Test
	void failedDirectoryDeletionIsReported(@TempDir Path root) throws Exception {
		Path owned = Files.createDirectory(root.resolve("native"));
		File directory = spy(owned.toFile());
		doReturn(false).when(directory).delete();
		SailRepository repository = mock(SailRepository.class);
		assertThrows(IOException.class, () -> QueryBenchmarkTest.cleanupRepository(repository, directory));
		verify(repository).shutDown();
		assertTrue(Files.exists(owned), "fixture must report retained files instead of silently succeeding");
	}

	@Test
	void setupWithoutRepositoryDeletesUnownedDirectory(@TempDir Path root) throws Exception {
		Path owned = Files.createDirectory(root.resolve("native"));
		QueryBenchmarkTest.cleanupRepository(null, owned.toFile());
		assertFalse(Files.exists(owned));
	}
}
